/* @lc app=leetcode id=2641 lang=kotlin */ class Solution { fun replaceValueInTree(root: TreeNode?): TreeNode? = generateSequence(listOf(root!!.also { it.`val` = 0 })) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.also { ch -> ch.sumOf { it.`val` }.let { tot -> f.forEach { p -> listOfNotNull(p.left, p.right).let { cs -> cs.sumOf { it.`val` }.let { sm -> cs.forEach { c -> c.`val` = tot - sm } } } } } }.takeIf { it.isNotEmpty() } }.count().let { root } }